import React from "react";
import {useVisualState} from "@synth/visuals-react";
export default function Shell(){const [step,setStep]=useVisualState("authored.step",0,{minimum:0,maximum:8});return <section><h2>Authored logical time</h2><p>Explicit acceptance fixture</p><input aria-label="Authored step" type="range" min={0} max={8} value={step} onChange={event=>setStep(Number(event.target.value))}/><output>Step {step}</output></section>}
